/**
 * Versioned, append-only schema migrations. Never edit a shipped migration;
 * add a new one with the next version number.
 *
 * Conventions
 * - IDs are stable opaque TEXT (generated by the app), never device file paths.
 * - Audio is referenced by platform content URI (`source_uri`), not a path.
 * - Timestamps are INTEGER milliseconds since epoch (UTC).
 * - Metadata provenance: `tracks` columns hold EMBEDDED tag values only and
 *   may be refreshed by rescans. Manual corrections live in
 *   `track_field_overrides` and `track_artists.source = 'manual'`, which
 *   rescans never touch. Effective value = override ?? embedded.
 */

export interface Migration {
  version: number;
  name: string;
  sql: string;
}

const NOW = "(CAST(strftime('%s','now') AS INTEGER) * 1000)";

export const MIGRATIONS: readonly Migration[] = [
  {
    version: 1,
    name: "core_library",
    sql: `
CREATE TABLE artists (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  sort_name TEXT,
  name_key TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW}
);

CREATE TABLE albums (
  id TEXT PRIMARY KEY NOT NULL,
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),
  title_key TEXT NOT NULL,
  album_artist_id TEXT REFERENCES artists(id) ON DELETE SET NULL,
  year INTEGER CHECK (year IS NULL OR year BETWEEN 0 AND 9999),
  artwork_ref TEXT,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW},
  UNIQUE (title_key, album_artist_id)
);
CREATE INDEX idx_albums_artist ON albums(album_artist_id);

CREATE TABLE tracks (
  id TEXT PRIMARY KEY NOT NULL,
  source_uri TEXT NOT NULL UNIQUE,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('mediastore', 'saf')),
  mediastore_id INTEGER,
  content_hash TEXT,
  mime_type TEXT,
  size_bytes INTEGER CHECK (size_bytes IS NULL OR size_bytes >= 0),
  source_modified_at INTEGER,
  is_available INTEGER NOT NULL DEFAULT 1 CHECK (is_available IN (0, 1)),
  title TEXT NOT NULL,
  album_id TEXT REFERENCES albums(id) ON DELETE SET NULL,
  track_number INTEGER CHECK (track_number IS NULL OR track_number > 0),
  disc_number INTEGER CHECK (disc_number IS NULL OR disc_number > 0),
  duration_ms INTEGER NOT NULL DEFAULT 0 CHECK (duration_ms >= 0),
  year INTEGER CHECK (year IS NULL OR year BETWEEN 0 AND 9999),
  genre TEXT,
  artwork_ref TEXT,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW}
);
CREATE INDEX idx_tracks_album ON tracks(album_id, disc_number, track_number);
CREATE INDEX idx_tracks_title ON tracks(title COLLATE NOCASE);
CREATE INDEX idx_tracks_hash ON tracks(content_hash);

CREATE TABLE track_artists (
  track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
  artist_id TEXT NOT NULL REFERENCES artists(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('primary', 'featured', 'composer', 'producer')),
  position INTEGER NOT NULL CHECK (position >= 0),
  source TEXT NOT NULL CHECK (source IN ('embedded', 'manual')),
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  PRIMARY KEY (track_id, source, role, position)
);
CREATE INDEX idx_track_artists_artist ON track_artists(artist_id);

CREATE TABLE track_field_overrides (
  track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
  field TEXT NOT NULL CHECK (field IN ('title', 'album_title', 'album_artist', 'track_number', 'disc_number', 'year', 'genre')),
  value TEXT,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW},
  PRIMARY KEY (track_id, field)
);

CREATE TABLE playlists (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  description TEXT,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW}
);

CREATE TABLE playlist_tracks (
  playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,
  position INTEGER NOT NULL CHECK (position >= 0),
  track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
  added_at INTEGER NOT NULL DEFAULT ${NOW},
  PRIMARY KEY (playlist_id, position)
);
CREATE INDEX idx_playlist_tracks_track ON playlist_tracks(track_id);

CREATE TABLE lyrics (
  id TEXT PRIMARY KEY NOT NULL,
  track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('static', 'line_synced', 'word_synced')),
  source TEXT NOT NULL CHECK (source IN ('manual', 'lrc_import', 'embedded_tag')),
  source_ref TEXT,
  language TEXT,
  offset_ms INTEGER NOT NULL DEFAULT 0,
  is_preferred INTEGER NOT NULL DEFAULT 0 CHECK (is_preferred IN (0, 1)),
  raw_text TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  updated_at INTEGER NOT NULL DEFAULT ${NOW}
);
CREATE INDEX idx_lyrics_track ON lyrics(track_id);
CREATE UNIQUE INDEX idx_lyrics_one_preferred ON lyrics(track_id) WHERE is_preferred = 1;

CREATE TABLE lyric_lines (
  lyrics_id TEXT NOT NULL REFERENCES lyrics(id) ON DELETE CASCADE,
  line_index INTEGER NOT NULL CHECK (line_index >= 0),
  start_ms INTEGER CHECK (start_ms IS NULL OR start_ms >= 0),
  end_ms INTEGER CHECK (end_ms IS NULL OR start_ms IS NULL OR end_ms >= start_ms),
  text TEXT NOT NULL,
  PRIMARY KEY (lyrics_id, line_index)
);

CREATE TABLE lyric_words (
  lyrics_id TEXT NOT NULL,
  line_index INTEGER NOT NULL,
  word_index INTEGER NOT NULL CHECK (word_index >= 0),
  start_ms INTEGER NOT NULL CHECK (start_ms >= 0),
  end_ms INTEGER CHECK (end_ms IS NULL OR end_ms >= start_ms),
  text TEXT NOT NULL,
  PRIMARY KEY (lyrics_id, line_index, word_index),
  FOREIGN KEY (lyrics_id, line_index) REFERENCES lyric_lines(lyrics_id, line_index) ON DELETE CASCADE
);

-- Polymorphic: entity existence is enforced by the repository layer.
CREATE TABLE favorites (
  entity_type TEXT NOT NULL CHECK (entity_type IN ('track', 'album', 'artist', 'playlist')),
  entity_id TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  PRIMARY KEY (entity_type, entity_id)
);

CREATE TABLE playback_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE,
  started_at INTEGER NOT NULL,
  played_ms INTEGER NOT NULL DEFAULT 0 CHECK (played_ms >= 0),
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX idx_history_started ON playback_history(started_at DESC);
CREATE INDEX idx_history_track ON playback_history(track_id);

CREATE TABLE app_preferences (
  key TEXT PRIMARY KEY NOT NULL,
  value_json TEXT NOT NULL CHECK (json_valid(value_json)),
  updated_at INTEGER NOT NULL DEFAULT ${NOW}
);
`,
  },
  {
    version: 2,
    name: "library_sources",
    sql: `
-- Where audio comes from. 'mediastore' is a single device-wide source;
-- 'saf' rows hold an opaque persisted tree URI and its display name only.
CREATE TABLE library_sources (
  id TEXT PRIMARY KEY NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('mediastore', 'saf')),
  tree_uri TEXT UNIQUE,
  display_name TEXT NOT NULL,
  last_scan_id TEXT,
  last_scanned_at INTEGER,
  last_scan_status TEXT CHECK (last_scan_status IS NULL OR last_scan_status IN ('completed', 'cancelled', 'failed')),
  created_at INTEGER NOT NULL DEFAULT ${NOW},
  CHECK ((kind = 'mediastore' AND tree_uri IS NULL) OR (kind = 'saf' AND tree_uri IS NOT NULL))
);

ALTER TABLE tracks ADD COLUMN source_id TEXT REFERENCES library_sources(id) ON DELETE SET NULL;
-- 'embedded' when the title came from tags, 'filename' when derived from the file name.
ALTER TABLE tracks ADD COLUMN title_source TEXT NOT NULL DEFAULT 'embedded' CHECK (title_source IN ('embedded', 'filename'));
ALTER TABLE tracks ADD COLUMN last_seen_scan_id TEXT;
CREATE INDEX idx_tracks_source ON tracks(source_id, last_seen_scan_id);
`,
  },
];
